  security_kind VARCHAR2(20 CHAR) DEFAULT 'COMMON_STOCK' NOT NULL,
  CONSTRAINT securities_pk PRIMARY KEY (security_id),
  CONSTRAINT securities_u1 UNIQUE (exchange_code, symbol),
  CONSTRAINT securities_f1 FOREIGN KEY (company_id) REFERENCES companies (company_id)
);
COMMENT ON TABLE securities IS 'Mã chứng khoán hiện tại, lịch sử đổi mã để mở rộng';
