CREATE TABLE source_artifacts (
  artifact_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
  source_id NUMBER(19) NOT NULL,
  artifact_kind VARCHAR2(12 CHAR) NOT NULL,
