  storage_path VARCHAR2(1000 CHAR) NOT NULL,
  source_url VARCHAR2(2000 CHAR),
  collected_at TIMESTAMP WITH TIME ZONE,
  hosting_note VARCHAR2(500 CHAR),
  CONSTRAINT source_artifacts_pk PRIMARY KEY (artifact_id),
  CONSTRAINT source_artifacts_u1 UNIQUE (source_id, sha256),
  CONSTRAINT source_artifacts_c1 CHECK (artifact_kind IN ('JSON','PDF','CSV','OTHER')),
  CONSTRAINT source_artifacts_c2 CHECK (REGEXP_LIKE(sha256, '^[0-9a-f]{64}$', 'c')),
  CONSTRAINT source_artifacts_f1 FOREIGN KEY (source_id) REFERENCES data_sources (source_id)
);
COMMENT ON TABLE source_artifacts IS 'Định danh bytes của JSON/PDF/CSV và provenance';
COMMENT ON COLUMN source_artifacts.artifact_id IS 'Surrogate ID, identity GENERATED BY DEFAULT ON NULL';
COMMENT ON COLUMN source_artifacts.source_id IS 'Nhà cung cấp/đơn vị phát hành';
