COMMENT ON COLUMN source_artifacts.storage_path IS 'Đường dẫn tệp bất biến';
COMMENT ON COLUMN source_artifacts.source_url IS 'URL thu thập';
COMMENT ON COLUMN source_artifacts.collected_at IS 'Ngày tải thực tế nếu biết; NULL khi không truy được, không thay bằng ngày đăng ký hay công bố';
COMMENT ON COLUMN source_artifacts.hosting_note IS 'Phân biệt issuer/mirror';

CREATE TABLE etl_batches (
  batch_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
  batch_key VARCHAR2(100 CHAR) NOT NULL,
  contract_version VARCHAR2(40 CHAR) NOT NULL,
  mapping_version VARCHAR2(40 CHAR) NOT NULL,
  batch_status VARCHAR2(16 CHAR) DEFAULT 'CREATED' NOT NULL,
  started_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  finished_at TIMESTAMP WITH TIME ZONE,
  received_count NUMBER(19) DEFAULT 0 NOT NULL,
  imported_count NUMBER(19) DEFAULT 0 NOT NULL,
  rejected_count NUMBER(19) DEFAULT 0 NOT NULL,
  skipped_count NUMBER(19) DEFAULT 0 NOT NULL,
  CONSTRAINT etl_batches_pk PRIMARY KEY (batch_id),
  CONSTRAINT etl_batches_u1 UNIQUE (batch_key),
  CONSTRAINT etl_batches_c1 CHECK (batch_status IN ('CREATED','STAGED','VALIDATED','IMPORTING','COMPLETED','PARTIAL','FAILED')),
  CONSTRAINT etl_batches_c2 CHECK (received_count >= 0 AND imported_count >= 0 AND rejected_count >= 0 AND skipped_count >= 0),
  CONSTRAINT etl_batches_c3 CHECK (finished_at IS NULL OR finished_at >= started_at)
);
COMMENT ON TABLE etl_batches IS 'Đợt nhập và trạng thái điều phối';
COMMENT ON COLUMN etl_batches.batch_id IS 'Surrogate ID, identity GENERATED BY DEFAULT ON NULL';
COMMENT ON COLUMN etl_batches.batch_key IS 'Khóa nhập lặp';
COMMENT ON COLUMN etl_batches.contract_version IS 'Phiên bản hợp đồng';
COMMENT ON COLUMN etl_batches.mapping_version IS 'Phiên bản mapping';
COMMENT ON COLUMN etl_batches.batch_status IS 'Trạng thái batch';
COMMENT ON COLUMN etl_batches.started_at IS 'Bắt đầu';
COMMENT ON COLUMN etl_batches.finished_at IS 'Kết thúc';
COMMENT ON COLUMN etl_batches.received_count IS 'Số dòng nhận';
COMMENT ON COLUMN etl_batches.imported_count IS 'Số nhập';
COMMENT ON COLUMN etl_batches.rejected_count IS 'Số từ chối';
COMMENT ON COLUMN etl_batches.skipped_count IS 'Số bỏ qua';

CREATE TABLE staging_facts (
  staging_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
