  CONSTRAINT staging_facts_u1 UNIQUE (batch_id, row_no),
  CONSTRAINT staging_facts_u2 UNIQUE (staging_id, batch_id),
  CONSTRAINT staging_facts_c1 CHECK (row_status IN ('PENDING','VALID','REJECTED','IMPORTED','SKIPPED')),
  CONSTRAINT staging_facts_f1 FOREIGN KEY (batch_id) REFERENCES etl_batches (batch_id),
  CONSTRAINT staging_facts_f2 FOREIGN KEY (artifact_id) REFERENCES source_artifacts (artifact_id)
);
COMMENT ON TABLE staging_facts IS 'Vùng nhận dữ liệu chưa tin cậy; không áp FK nghiệp vụ lên mã đầu vào';
COMMENT ON COLUMN staging_facts.staging_id IS 'Surrogate ID, identity GENERATED BY DEFAULT ON NULL';
