COMMENT ON COLUMN staging_facts.artifact_id IS 'Artifact nguồn';
COMMENT ON COLUMN staging_facts.source_symbol IS 'Mã thô';
COMMENT ON COLUMN staging_facts.fiscal_year_raw IS 'Năm thô để ghi được dữ liệu lỗi';
COMMENT ON COLUMN staging_facts.item_code_raw IS 'Chỉ tiêu thô';
COMMENT ON COLUMN staging_facts.value_text IS 'Giá trị thô';
