COMMENT ON COLUMN staging_facts.payload IS 'Payload đầy đủ';

CREATE TABLE etl_errors (
  error_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
  batch_id NUMBER(19) NOT NULL,
