);
COMMENT ON TABLE etl_errors IS 'Lỗi nhập tồn tại sau rollback nghiệp vụ';
COMMENT ON COLUMN etl_errors.error_id IS 'Surrogate ID, identity GENERATED BY DEFAULT ON NULL';
COMMENT ON COLUMN etl_errors.batch_id IS 'Batch';
COMMENT ON COLUMN etl_errors.staging_id IS 'Dòng staging';
COMMENT ON COLUMN etl_errors.error_code IS 'Mã lỗi';
COMMENT ON COLUMN etl_errors.error_message IS 'Nội dung lỗi';
COMMENT ON COLUMN etl_errors.logged_at IS 'Thời điểm';

