CREATE TABLE financial_reports (
  report_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
  company_id NUMBER(19) NOT NULL,
  fiscal_year NUMBER(4) NOT NULL,
  period_kind VARCHAR2(10 CHAR) DEFAULT 'ANNUAL' NOT NULL,
  statement_kind VARCHAR2(2 CHAR) NOT NULL,
  scope_code VARCHAR2(16 CHAR) DEFAULT 'UNKNOWN' NOT NULL,
  source_report_type VARCHAR2(20 CHAR) NOT NULL,
  artifact_id NUMBER(19) NOT NULL,
  mapping_version VARCHAR2(40 CHAR) NOT NULL,
  report_version NUMBER(6) DEFAULT 1 NOT NULL,
  fiscal_start DATE,
  fiscal_end DATE,
  publication_at TIMESTAMP WITH TIME ZONE,
  publication_artifact_id NUMBER(19),
  currency_code VARCHAR2(7 CHAR) DEFAULT 'UNKNOWN' NOT NULL,
  original_unit VARCHAR2(20 CHAR) DEFAULT 'UNKNOWN' NOT NULL,
  unit_multiplier NUMBER(10),
  metadata_status VARCHAR2(12 CHAR) DEFAULT 'PENDING' NOT NULL,
  batch_id NUMBER(19) NOT NULL,
  CONSTRAINT financial_reports_pk PRIMARY KEY (report_id),
  CONSTRAINT financial_reports_u1 UNIQUE (company_id, fiscal_year, period_kind, statement_kind, scope_code, artifact_id, mapping_version, report_version),
  CONSTRAINT financial_reports_u2 UNIQUE (report_id, statement_kind),
  CONSTRAINT financial_reports_c1 CHECK (statement_kind IN ('BS','IS','CF')),
  CONSTRAINT financial_reports_c2 CHECK (scope_code IN ('UNKNOWN','CONSOLIDATED','SEPARATE')),
  CONSTRAINT financial_reports_c3 CHECK (period_kind = 'ANNUAL'),
  CONSTRAINT financial_reports_c4 CHECK (fiscal_year BETWEEN 1900 AND 2200),
  CONSTRAINT financial_reports_c5 CHECK (report_version > 0),
  CONSTRAINT financial_reports_c6 CHECK (metadata_status IN ('PENDING','VERIFIED')),
  CONSTRAINT financial_reports_c7 CHECK ((fiscal_start IS NULL AND fiscal_end IS NULL) OR (fiscal_start IS NOT NULL AND fiscal_end IS NOT NULL AND fiscal_end >= fiscal_start)),
  CONSTRAINT financial_reports_c8 CHECK (unit_multiplier IS NULL OR unit_multiplier IN (1,1000,1000000)),
  CONSTRAINT financial_reports_c9 CHECK ((publication_at IS NULL AND publication_artifact_id IS NULL) OR (publication_at IS NOT NULL AND publication_artifact_id IS NOT NULL)),
  CONSTRAINT financial_reports_c10 CHECK (metadata_status <> 'VERIFIED' OR (scope_code <> 'UNKNOWN' AND fiscal_start IS NOT NULL AND fiscal_end IS NOT NULL AND currency_code = 'VND' AND original_unit <> 'UNKNOWN' AND unit_multiplier IS NOT NULL)),
  CONSTRAINT financial_reports_f1 FOREIGN KEY (company_id) REFERENCES companies (company_id),
  CONSTRAINT financial_reports_f2 FOREIGN KEY (artifact_id) REFERENCES source_artifacts (artifact_id),
  CONSTRAINT financial_reports_f3 FOREIGN KEY (publication_artifact_id) REFERENCES source_artifacts (artifact_id),
  CONSTRAINT financial_reports_f4 FOREIGN KEY (batch_id) REFERENCES etl_batches (batch_id)
);
COMMENT ON TABLE financial_reports IS 'Phiên bản một loại BCTC của một kỳ/phạm vi';
COMMENT ON COLUMN financial_reports.report_id IS 'Surrogate ID, identity GENERATED BY DEFAULT ON NULL';
COMMENT ON COLUMN financial_reports.company_id IS 'Doanh nghiệp';
COMMENT ON COLUMN financial_reports.fiscal_year IS 'Năm báo cáo';
COMMENT ON COLUMN financial_reports.period_kind IS 'Năm trong MVP';
COMMENT ON COLUMN financial_reports.statement_kind IS 'BS/IS/CF';
COMMENT ON COLUMN financial_reports.scope_code IS 'Phạm vi canonical';
COMMENT ON COLUMN financial_reports.source_report_type IS 'Mã nguồn HK/...';
COMMENT ON COLUMN financial_reports.artifact_id IS 'Artifact gốc';
COMMENT ON COLUMN financial_reports.mapping_version IS 'Mapping đã dùng';
COMMENT ON COLUMN financial_reports.report_version IS 'Phiên bản kể cả review metadata';
COMMENT ON COLUMN financial_reports.fiscal_start IS 'Ngày đầu niên độ xác minh';
COMMENT ON COLUMN financial_reports.fiscal_end IS 'Ngày cuối niên độ xác minh';
COMMENT ON COLUMN financial_reports.publication_at IS 'Thời điểm công bố có bằng chứng';
COMMENT ON COLUMN financial_reports.publication_artifact_id IS 'Bằng chứng công bố';
COMMENT ON COLUMN financial_reports.currency_code IS 'VND/UNKNOWN';
