COMMENT ON COLUMN financial_reports.metadata_status IS 'Scope/fiscal/unit đã kiểm chứng?';
COMMENT ON COLUMN financial_reports.batch_id IS 'Batch nhập';

CREATE TABLE financial_facts (
  fact_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
  report_id NUMBER(19) NOT NULL,
  item_id NUMBER(19) NOT NULL,
  statement_kind VARCHAR2(2 CHAR) NOT NULL,
  value_text VARCHAR2(200 CHAR),
  value_original NUMBER(38,6),
  value_vnd NUMBER(28,0),
  quality_status VARCHAR2(12 CHAR) NOT NULL,
  raw_locator VARCHAR2(1000 CHAR) NOT NULL,
  raw_code VARCHAR2(80 CHAR) NOT NULL,
  raw_name VARCHAR2(500 CHAR),
  CONSTRAINT financial_facts_pk PRIMARY KEY (fact_id),
  CONSTRAINT financial_facts_u1 UNIQUE (report_id, item_id),
  CONSTRAINT financial_facts_u2 UNIQUE (fact_id, report_id, item_id),
  CONSTRAINT financial_facts_u3 UNIQUE (fact_id, item_id),
  CONSTRAINT financial_facts_u4 UNIQUE (fact_id, report_id),
  CONSTRAINT financial_facts_c1 CHECK (quality_status IN ('MISSING','PROVISIONAL','BLOCKED','VERIFIED')),
  CONSTRAINT financial_facts_c2 CHECK ((quality_status = 'MISSING' AND value_original IS NULL AND value_vnd IS NULL) OR (quality_status <> 'MISSING' AND value_original IS NOT NULL)),
  CONSTRAINT financial_facts_c3 CHECK (quality_status <> 'VERIFIED' OR value_vnd IS NOT NULL),
  CONSTRAINT financial_facts_f1 FOREIGN KEY (report_id, statement_kind) REFERENCES financial_reports (report_id, statement_kind),
  CONSTRAINT financial_facts_f2 FOREIGN KEY (item_id, statement_kind) REFERENCES financial_items (item_id, statement_kind)
);
COMMENT ON TABLE financial_facts IS 'Giá trị nguồn bất biến, một item trong report version';
COMMENT ON COLUMN financial_facts.fact_id IS 'Surrogate ID, identity GENERATED BY DEFAULT ON NULL';
COMMENT ON COLUMN financial_facts.report_id IS 'Report version';
COMMENT ON COLUMN financial_facts.item_id IS 'Chỉ tiêu';
COMMENT ON COLUMN financial_facts.statement_kind IS 'Khóa lan truyền để ngăn item sai statement';
COMMENT ON COLUMN financial_facts.value_text IS 'Giá trị nguồn dạng text';
COMMENT ON COLUMN financial_facts.value_original IS 'Số nguồn';
COMMENT ON COLUMN financial_facts.value_vnd IS 'Số VND chỉ sau xác minh đơn vị';
COMMENT ON COLUMN financial_facts.quality_status IS 'Trạng thái fact';
COMMENT ON COLUMN financial_facts.raw_locator IS 'Selector nguồn';
COMMENT ON COLUMN financial_facts.raw_code IS 'Mã chỉ tiêu nguồn';
COMMENT ON COLUMN financial_facts.raw_name IS 'Tên chỉ tiêu nguồn';

CREATE TABLE fact_corrections (
  correction_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
  fact_id NUMBER(19) NOT NULL,
  correction_key VARCHAR2(100 CHAR) NOT NULL,
  new_value_original NUMBER(38,6) NOT NULL,
  new_value_vnd NUMBER(28,0),
  evidence_artifact_id NUMBER(19) NOT NULL,
  evidence_page NUMBER(6) NOT NULL,
  reason VARCHAR2(1000 CHAR) NOT NULL,
  review_status VARCHAR2(16 CHAR) NOT NULL,
  reviewed_by VARCHAR2(100 CHAR),
  reviewed_at TIMESTAMP WITH TIME ZONE,
  supersedes_id NUMBER(19),
  CONSTRAINT fact_corrections_pk PRIMARY KEY (correction_id),
  CONSTRAINT fact_corrections_u1 UNIQUE (correction_key),
  CONSTRAINT fact_corrections_u2 UNIQUE (correction_id, fact_id),
  CONSTRAINT fact_corrections_c1 CHECK (review_status IN ('PROVISIONAL','AUTO_REVIEWED','APPROVED','REJECTED')),
  CONSTRAINT fact_corrections_c2 CHECK (evidence_page > 0),
  CONSTRAINT fact_corrections_c3 CHECK (review_status NOT IN ('AUTO_REVIEWED','APPROVED') OR (reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL)),
  CONSTRAINT fact_corrections_c4 CHECK (supersedes_id IS NULL OR supersedes_id <> correction_id),
  CONSTRAINT fact_corrections_f1 FOREIGN KEY (fact_id) REFERENCES financial_facts (fact_id),
  CONSTRAINT fact_corrections_f2 FOREIGN KEY (evidence_artifact_id) REFERENCES source_artifacts (artifact_id),
  CONSTRAINT fact_corrections_f3 FOREIGN KEY (supersedes_id, fact_id) REFERENCES fact_corrections (correction_id, fact_id)
);
COMMENT ON TABLE fact_corrections IS 'Correction bất biến về số, bằng chứng review riêng';
COMMENT ON COLUMN fact_corrections.correction_id IS 'Surrogate ID, identity GENERATED BY DEFAULT ON NULL';
COMMENT ON COLUMN fact_corrections.fact_id IS 'Fact gốc';
COMMENT ON COLUMN fact_corrections.correction_key IS 'ID ngoài/bộ mẫu';
COMMENT ON COLUMN fact_corrections.new_value_original IS 'Giá trị sửa';
COMMENT ON COLUMN fact_corrections.new_value_vnd IS 'Số VND sau xác minh';
COMMENT ON COLUMN fact_corrections.evidence_artifact_id IS 'PDF/bằng chứng';
COMMENT ON COLUMN fact_corrections.evidence_page IS 'Trang PDF 1-based';
COMMENT ON COLUMN fact_corrections.reason IS 'Lý do';
COMMENT ON COLUMN fact_corrections.review_status IS 'Tự động hoặc human review';
COMMENT ON COLUMN fact_corrections.reviewed_by IS 'Reviewer thực tế';
COMMENT ON COLUMN fact_corrections.reviewed_at IS 'Ngày review';
COMMENT ON COLUMN fact_corrections.supersedes_id IS 'Correction trước cùng fact';

CREATE TABLE report_sets (
  report_set_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
  company_id NUMBER(19) NOT NULL,
  fiscal_year NUMBER(4) NOT NULL,
  scope_code VARCHAR2(16 CHAR) NOT NULL,
  selection_version NUMBER(6) NOT NULL,
  dataset_version VARCHAR2(60 CHAR) NOT NULL,
  set_state VARCHAR2(8 CHAR) DEFAULT 'DRAFT' NOT NULL,
  acceptance_status VARCHAR2(12 CHAR) DEFAULT 'PENDING' NOT NULL,
  temporal_mode VARCHAR2(16 CHAR) DEFAULT 'RETROSPECTIVE' NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT report_sets_pk PRIMARY KEY (report_set_id),
  CONSTRAINT report_sets_u1 UNIQUE (company_id, fiscal_year, scope_code, selection_version),
  CONSTRAINT report_sets_u2 UNIQUE (report_set_id, company_id, fiscal_year, scope_code),
  CONSTRAINT report_sets_c1 CHECK (scope_code IN ('UNKNOWN','CONSOLIDATED','SEPARATE')),
  CONSTRAINT report_sets_c2 CHECK (set_state IN ('DRAFT','FROZEN')),
  CONSTRAINT report_sets_c3 CHECK (acceptance_status IN ('PENDING','VERIFIED')),
  CONSTRAINT report_sets_c4 CHECK (temporal_mode = 'RETROSPECTIVE'),
  CONSTRAINT report_sets_c5 CHECK (selection_version > 0),
  CONSTRAINT report_sets_c6 CHECK (fiscal_year BETWEEN 1900 AND 2200),
  CONSTRAINT report_sets_f1 FOREIGN KEY (company_id) REFERENCES companies (company_id)
);
COMMENT ON TABLE report_sets IS 'Snapshot lựa chọn bất biến, gồm ba BCTC và effective facts';
COMMENT ON COLUMN report_sets.report_set_id IS 'Surrogate ID, identity GENERATED BY DEFAULT ON NULL';
COMMENT ON COLUMN report_sets.company_id IS 'Doanh nghiệp';
COMMENT ON COLUMN report_sets.fiscal_year IS 'Năm';
COMMENT ON COLUMN report_sets.scope_code IS 'Phạm vi canonical';
COMMENT ON COLUMN report_sets.selection_version IS 'Phiên bản lựa chọn';
COMMENT ON COLUMN report_sets.dataset_version IS 'Phiên bản dataset';
COMMENT ON COLUMN report_sets.set_state IS 'DRAFT/FROZEN';
COMMENT ON COLUMN report_sets.acceptance_status IS 'PENDING/VERIFIED';
COMMENT ON COLUMN report_sets.temporal_mode IS 'MVP hồi cứu';
COMMENT ON COLUMN report_sets.created_at IS 'Thời điểm snapshot';

CREATE TABLE report_set_members (
