CREATE TABLE report_set_facts (
  selection_fact_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
  report_set_id NUMBER(19) NOT NULL,
  report_id NUMBER(19) NOT NULL,
  item_id NUMBER(19) NOT NULL,
  fact_id NUMBER(19) NOT NULL,
  correction_id NUMBER(19),
  selected_quality VARCHAR2(12 CHAR) NOT NULL,
  CONSTRAINT report_set_facts_pk PRIMARY KEY (selection_fact_id),
  CONSTRAINT report_set_facts_u1 UNIQUE (report_set_id, item_id),
  CONSTRAINT report_set_facts_c1 CHECK (selected_quality IN ('MISSING','PROVISIONAL','BLOCKED','VERIFIED')),
  CONSTRAINT report_set_facts_f1 FOREIGN KEY (report_set_id, report_id) REFERENCES report_set_members (report_set_id, report_id),
  CONSTRAINT report_set_facts_f2 FOREIGN KEY (fact_id, report_id, item_id) REFERENCES financial_facts (fact_id, report_id, item_id),
  CONSTRAINT report_set_facts_f3 FOREIGN KEY (correction_id, fact_id) REFERENCES fact_corrections (correction_id, fact_id)
);
COMMENT ON TABLE report_set_facts IS 'Snapshot chọn fact + correction cụ thể, không đọc correction mới nhất ngầm';
COMMENT ON COLUMN report_set_facts.selection_fact_id IS 'Surrogate ID, identity GENERATED BY DEFAULT ON NULL';
COMMENT ON COLUMN report_set_facts.report_set_id IS 'Snapshot';
COMMENT ON COLUMN report_set_facts.report_id IS 'Report thuộc snapshot';
COMMENT ON COLUMN report_set_facts.item_id IS 'Chỉ tiêu';
COMMENT ON COLUMN report_set_facts.fact_id IS 'Fact gốc';
COMMENT ON COLUMN report_set_facts.correction_id IS 'Correction được chọn hoặc NULL';
COMMENT ON COLUMN report_set_facts.selected_quality IS 'Chất lượng tại thời điểm khóa snapshot';

CREATE TABLE report_heads (
  company_id NUMBER(19) NOT NULL,
  fiscal_year NUMBER(4) NOT NULL,
  scope_code VARCHAR2(16 CHAR) NOT NULL,
  report_set_id NUMBER(19) NOT NULL,
  lock_version NUMBER(10) DEFAULT 1 NOT NULL,
  CONSTRAINT report_heads_pk PRIMARY KEY (company_id, fiscal_year, scope_code),
  CONSTRAINT report_heads_c1 CHECK (lock_version > 0),
  CONSTRAINT report_heads_f1 FOREIGN KEY (report_set_id, company_id, fiscal_year, scope_code) REFERENCES report_sets (report_set_id, company_id, fiscal_year, scope_code)
);
COMMENT ON TABLE report_heads IS 'Con trỏ hiện hành; lịch sử ở report_sets và change log';
COMMENT ON COLUMN report_heads.company_id IS 'Doanh nghiệp';
COMMENT ON COLUMN report_heads.fiscal_year IS 'Năm';
COMMENT ON COLUMN report_heads.scope_code IS 'Phạm vi';
COMMENT ON COLUMN report_heads.report_set_id IS 'Snapshot được chọn';
COMMENT ON COLUMN report_heads.lock_version IS 'Optimistic version';

CREATE TABLE metric_definitions (
  metric_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
  metric_code VARCHAR2(60 CHAR) NOT NULL,
  formula_version VARCHAR2(20 CHAR) NOT NULL,
  metric_name VARCHAR2(200 CHAR) NOT NULL,
  formula_text VARCHAR2(1000 CHAR) NOT NULL,
  display_unit VARCHAR2(10 CHAR) NOT NULL,
  decimal_places NUMBER(2) DEFAULT 12 NOT NULL,
  CONSTRAINT metric_definitions_pk PRIMARY KEY (metric_id),
  CONSTRAINT metric_definitions_u1 UNIQUE (metric_code, formula_version),
  CONSTRAINT metric_definitions_c1 CHECK (display_unit IN ('PERCENT','TIMES')),
  CONSTRAINT metric_definitions_c2 CHECK (decimal_places = 12)
);
COMMENT ON TABLE metric_definitions IS 'Danh mục công thức có phiên bản; SQL implementation ngoài metadata';
COMMENT ON COLUMN metric_definitions.metric_id IS 'Surrogate ID, identity GENERATED BY DEFAULT ON NULL';
COMMENT ON COLUMN metric_definitions.metric_code IS 'Mã chỉ số';
COMMENT ON COLUMN metric_definitions.formula_version IS 'SemVer';
COMMENT ON COLUMN metric_definitions.metric_name IS 'Tên chỉ số';
COMMENT ON COLUMN metric_definitions.formula_text IS 'Công thức để giải thích';
COMMENT ON COLUMN metric_definitions.display_unit IS 'PERCENT/TIMES';
COMMENT ON COLUMN metric_definitions.decimal_places IS 'Số chữ số lưu';

CREATE TABLE metric_dependencies (
  metric_id NUMBER(19) NOT NULL,
  input_position NUMBER(2) NOT NULL,
  item_id NUMBER(19) NOT NULL,
  year_offset NUMBER(2) NOT NULL,
  CONSTRAINT metric_dependencies_pk PRIMARY KEY (metric_id, input_position),
  CONSTRAINT metric_dependencies_c1 CHECK (input_position >= 0),
  CONSTRAINT metric_dependencies_c2 CHECK (year_offset IN (0,-1)),
  CONSTRAINT metric_dependencies_f1 FOREIGN KEY (metric_id) REFERENCES metric_definitions (metric_id),
  CONSTRAINT metric_dependencies_f2 FOREIGN KEY (item_id) REFERENCES financial_items (item_id)
);
COMMENT ON TABLE metric_dependencies IS 'Đặc tả đầu vào từng công thức theo năm tương đối';
COMMENT ON COLUMN metric_dependencies.metric_id IS 'Công thức';
COMMENT ON COLUMN metric_dependencies.input_position IS 'Vị trí';
COMMENT ON COLUMN metric_dependencies.item_id IS 'Chỉ tiêu';
COMMENT ON COLUMN metric_dependencies.year_offset IS '0 hoặc -1';

CREATE TABLE calculation_runs (
  run_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
  run_key VARCHAR2(100 CHAR) NOT NULL,
  report_set_id NUMBER(19) NOT NULL,
  previous_set_id NUMBER(19),
  engine_version VARCHAR2(40 CHAR) NOT NULL,
  run_status VARCHAR2(12 CHAR) DEFAULT 'CREATED' NOT NULL,
  started_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT calculation_runs_pk PRIMARY KEY (run_id),
  CONSTRAINT calculation_runs_u1 UNIQUE (run_key),
  CONSTRAINT calculation_runs_c1 CHECK (run_status IN ('CREATED','RUNNING','COMPLETED','FAILED')),
  CONSTRAINT calculation_runs_c2 CHECK (previous_set_id IS NULL OR previous_set_id <> report_set_id),
  CONSTRAINT calculation_runs_f1 FOREIGN KEY (report_set_id) REFERENCES report_sets (report_set_id),
  CONSTRAINT calculation_runs_f2 FOREIGN KEY (previous_set_id) REFERENCES report_sets (report_set_id)
);
COMMENT ON TABLE calculation_runs IS 'Một lần tính gắn snapshot hiện tại và snapshot năm trước chính xác';
COMMENT ON COLUMN calculation_runs.run_id IS 'Surrogate ID, identity GENERATED BY DEFAULT ON NULL';
COMMENT ON COLUMN calculation_runs.run_key IS 'Khóa idempotency';
COMMENT ON COLUMN calculation_runs.report_set_id IS 'Snapshot năm t';
COMMENT ON COLUMN calculation_runs.previous_set_id IS 'Snapshot năm t-1, NULL nếu thiếu';
COMMENT ON COLUMN calculation_runs.engine_version IS 'Phiên bản code SQL/PLSQL';
COMMENT ON COLUMN calculation_runs.run_status IS 'Trạng thái';
COMMENT ON COLUMN calculation_runs.started_at IS 'Thời điểm';

CREATE TABLE metric_results (
  result_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
  run_id NUMBER(19) NOT NULL,
  metric_id NUMBER(19) NOT NULL,
  metric_value NUMBER(28,12),
  result_status VARCHAR2(28 CHAR) NOT NULL,
  reason_codes VARCHAR2(1000 CHAR),
  CONSTRAINT metric_results_pk PRIMARY KEY (result_id),
  CONSTRAINT metric_results_u1 UNIQUE (run_id, metric_id),
  CONSTRAINT metric_results_c1 CHECK (result_status IN ('CALCULATED_PROVISIONAL','VALID','MISSING_INPUT','INVALID_DENOMINATOR','BLOCKED_INPUT_QUALITY')),
  CONSTRAINT metric_results_c2 CHECK ((result_status IN ('CALCULATED_PROVISIONAL','VALID') AND metric_value IS NOT NULL) OR (result_status NOT IN ('CALCULATED_PROVISIONAL','VALID') AND metric_value IS NULL)),
  CONSTRAINT metric_results_f1 FOREIGN KEY (run_id) REFERENCES calculation_runs (run_id),
  CONSTRAINT metric_results_f2 FOREIGN KEY (metric_id) REFERENCES metric_definitions (metric_id)
);
COMMENT ON TABLE metric_results IS 'Kết quả lưu sẵn có lineage để tái lập và sàng lọc';
COMMENT ON COLUMN metric_results.result_id IS 'Surrogate ID, identity GENERATED BY DEFAULT ON NULL';
COMMENT ON COLUMN metric_results.run_id IS 'Lần tính';
COMMENT ON COLUMN metric_results.metric_id IS 'Công thức';
COMMENT ON COLUMN metric_results.metric_value IS 'Ratio thuần; NULL khi không tính được';
COMMENT ON COLUMN metric_results.result_status IS 'Trạng thái';
COMMENT ON COLUMN metric_results.reason_codes IS 'Mã lý do, không dùng để thay quan hệ';

CREATE TABLE metric_input_facts (
  result_id NUMBER(19) NOT NULL,
  input_position NUMBER(2) NOT NULL,
  selection_fact_id NUMBER(19) NOT NULL,
  CONSTRAINT metric_input_facts_pk PRIMARY KEY (result_id, input_position),
  CONSTRAINT metric_input_facts_c1 CHECK (input_position >= 0),
  CONSTRAINT metric_input_facts_f1 FOREIGN KEY (result_id) REFERENCES metric_results (result_id),
  CONSTRAINT metric_input_facts_f2 FOREIGN KEY (selection_fact_id) REFERENCES report_set_facts (selection_fact_id)
);
COMMENT ON TABLE metric_input_facts IS 'Mỗi đầu vào chỉ đúng effective fact của snapshot bất biến';
COMMENT ON COLUMN metric_input_facts.result_id IS 'Kết quả';
COMMENT ON COLUMN metric_input_facts.input_position IS 'Vị trí';
COMMENT ON COLUMN metric_input_facts.selection_fact_id IS 'Effective fact cụ thể';

CREATE TABLE quality_issues (
  issue_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
  report_id NUMBER(19) NOT NULL,
  fact_id NUMBER(19),
  rule_code VARCHAR2(60 CHAR) NOT NULL,
  severity VARCHAR2(8 CHAR) NOT NULL,
  issue_status VARCHAR2(24 CHAR) NOT NULL,
  details VARCHAR2(2000 CHAR) NOT NULL,
  evidence_artifact_id NUMBER(19),
  CONSTRAINT quality_issues_pk PRIMARY KEY (issue_id),
  CONSTRAINT quality_issues_c1 CHECK (severity IN ('LOW','MEDIUM','HIGH','CRITICAL')),
  CONSTRAINT quality_issues_c2 CHECK (issue_status IN ('OPEN','MITIGATED_PROVISIONAL','RESOLVED')),
  CONSTRAINT quality_issues_f1 FOREIGN KEY (report_id) REFERENCES financial_reports (report_id),
  CONSTRAINT quality_issues_f2 FOREIGN KEY (fact_id, report_id) REFERENCES financial_facts (fact_id, report_id),
  CONSTRAINT quality_issues_f3 FOREIGN KEY (evidence_artifact_id) REFERENCES source_artifacts (artifact_id)
);
COMMENT ON TABLE quality_issues IS 'Lỗi chất lượng report/fact với rule và vòng đời xử lý';
COMMENT ON COLUMN quality_issues.issue_id IS 'Surrogate ID, identity GENERATED BY DEFAULT ON NULL';
COMMENT ON COLUMN quality_issues.report_id IS 'Report bị ảnh hưởng';
COMMENT ON COLUMN quality_issues.fact_id IS 'Fact khi lỗi cục bộ';
COMMENT ON COLUMN quality_issues.rule_code IS 'Quy tắc';
COMMENT ON COLUMN quality_issues.severity IS 'Mức độ';
COMMENT ON COLUMN quality_issues.issue_status IS 'Trạng thái';
COMMENT ON COLUMN quality_issues.details IS 'Chi tiết';
COMMENT ON COLUMN quality_issues.evidence_artifact_id IS 'Bằng chứng bổ sung';

CREATE TABLE business_change_log (
  change_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
  entity_name VARCHAR2(60 CHAR) NOT NULL,
  entity_key VARCHAR2(200 CHAR) NOT NULL,
  action_code VARCHAR2(10 CHAR) NOT NULL,
  old_data CLOB,
  new_data CLOB,
  actor_name VARCHAR2(128 CHAR) NOT NULL,
  changed_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT business_change_log_pk PRIMARY KEY (change_id),
  CONSTRAINT business_change_log_c1 CHECK (action_code IN ('INSERT','UPDATE','DELETE'))
);
COMMENT ON TABLE business_change_log IS 'Lịch sử thay đổi metadata/con trỏ; không thay database audit';
COMMENT ON COLUMN business_change_log.change_id IS 'Surrogate ID, identity GENERATED BY DEFAULT ON NULL';
COMMENT ON COLUMN business_change_log.entity_name IS 'Tên bảng nghiệp vụ';
COMMENT ON COLUMN business_change_log.entity_key IS 'Khóa nghiệp vụ dạng text';
COMMENT ON COLUMN business_change_log.action_code IS 'INSERT/UPDATE/DELETE';
COMMENT ON COLUMN business_change_log.old_data IS 'Trước thay đổi';
COMMENT ON COLUMN business_change_log.new_data IS 'Sau thay đổi';
COMMENT ON COLUMN business_change_log.actor_name IS 'DB session user';
COMMENT ON COLUMN business_change_log.changed_at IS 'Thời điểm';

CREATE TABLE daily_prices (
  price_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
  security_id NUMBER(19) NOT NULL,
  trading_date DATE NOT NULL,
  artifact_id NUMBER(19) NOT NULL,
  price_basis VARCHAR2(12 CHAR) NOT NULL,
  currency_code VARCHAR2(7 CHAR) NOT NULL,
  price_multiplier NUMBER(10),
  open_price NUMBER(20,6),
  high_price NUMBER(20,6),
  low_price NUMBER(20,6),
  close_price NUMBER(20,6) NOT NULL,
  volume NUMBER(24,0),
  CONSTRAINT daily_prices_pk PRIMARY KEY (price_id),
  CONSTRAINT daily_prices_u1 UNIQUE (security_id, trading_date, artifact_id, price_basis),
  CONSTRAINT daily_prices_c1 CHECK (price_basis IN ('ADJUSTED','UNADJUSTED','UNKNOWN')),
  CONSTRAINT daily_prices_c2 CHECK (trading_date = TRUNC(trading_date)),
  CONSTRAINT daily_prices_c3 CHECK (close_price >= 0),
  CONSTRAINT daily_prices_c4 CHECK (open_price IS NULL OR open_price >= 0),
  CONSTRAINT daily_prices_c5 CHECK (low_price IS NULL OR low_price >= 0),
  CONSTRAINT daily_prices_c6 CHECK (high_price IS NULL OR high_price >= 0),
  CONSTRAINT daily_prices_c7 CHECK (volume IS NULL OR volume >= 0),
  CONSTRAINT daily_prices_c8 CHECK (high_price IS NULL OR low_price IS NULL OR high_price >= low_price),
  CONSTRAINT daily_prices_c9 CHECK (high_price IS NULL OR high_price >= close_price),
  CONSTRAINT daily_prices_c10 CHECK (low_price IS NULL OR low_price <= close_price),
  CONSTRAINT daily_prices_c11 CHECK (high_price IS NULL OR open_price IS NULL OR high_price >= open_price),
  CONSTRAINT daily_prices_c12 CHECK (low_price IS NULL OR open_price IS NULL OR low_price <= open_price),
  CONSTRAINT daily_prices_c13 CHECK (price_multiplier IS NULL OR price_multiplier IN (1,1000,1000000)),
  CONSTRAINT daily_prices_f1 FOREIGN KEY (security_id) REFERENCES securities (security_id),
  CONSTRAINT daily_prices_f2 FOREIGN KEY (artifact_id) REFERENCES source_artifacts (artifact_id)
);
COMMENT ON TABLE daily_prices IS 'Giá ngày có phiên bản nguồn; chưa có dataset nghiệm thu';
COMMENT ON COLUMN daily_prices.price_id IS 'Surrogate ID, identity GENERATED BY DEFAULT ON NULL';
COMMENT ON COLUMN daily_prices.security_id IS 'Chứng khoán';
COMMENT ON COLUMN daily_prices.trading_date IS 'Ngày giao dịch không có phần giờ';
COMMENT ON COLUMN daily_prices.artifact_id IS 'Nguồn phiên bản';
COMMENT ON COLUMN daily_prices.price_basis IS 'ADJUSTED/UNADJUSTED/UNKNOWN';
COMMENT ON COLUMN daily_prices.currency_code IS 'VND/UNKNOWN';
COMMENT ON COLUMN daily_prices.price_multiplier IS 'Hệ số sang VND';
COMMENT ON COLUMN daily_prices.open_price IS 'Giá mở cửa';
COMMENT ON COLUMN daily_prices.high_price IS 'Giá cao';
COMMENT ON COLUMN daily_prices.low_price IS 'Giá thấp';
COMMENT ON COLUMN daily_prices.close_price IS 'Giá đóng cửa';
COMMENT ON COLUMN daily_prices.volume IS 'Khối lượng';
CREATE INDEX securities_ix1 ON securities (company_id);
CREATE INDEX staging_facts_ix2 ON staging_facts (artifact_id);
CREATE INDEX etl_errors_ix1 ON etl_errors (batch_id);
CREATE INDEX etl_errors_ix2 ON etl_errors (staging_id, batch_id);
CREATE INDEX financial_reports_ix2 ON financial_reports (artifact_id);
CREATE INDEX financial_reports_ix3 ON financial_reports (publication_artifact_id);
CREATE INDEX financial_reports_ix4 ON financial_reports (batch_id);
CREATE INDEX financial_facts_ix1 ON financial_facts (report_id, statement_kind);
CREATE INDEX financial_facts_ix2 ON financial_facts (item_id, statement_kind);
CREATE INDEX fact_corrections_ix1 ON fact_corrections (fact_id);
CREATE INDEX fact_corrections_ix2 ON fact_corrections (evidence_artifact_id);
CREATE INDEX fact_corrections_ix3 ON fact_corrections (supersedes_id, fact_id);
CREATE INDEX report_set_members_ix2 ON report_set_members (report_id, statement_kind);
CREATE INDEX report_set_facts_ix1 ON report_set_facts (report_set_id, report_id);
CREATE INDEX report_set_facts_ix2 ON report_set_facts (fact_id, report_id, item_id);
CREATE INDEX report_set_facts_ix3 ON report_set_facts (correction_id, fact_id);
CREATE INDEX report_heads_ix1 ON report_heads (report_set_id, company_id, fiscal_year, scope_code);
CREATE INDEX metric_dependencies_ix2 ON metric_dependencies (item_id);
CREATE INDEX calculation_runs_ix1 ON calculation_runs (report_set_id);
CREATE INDEX calculation_runs_ix2 ON calculation_runs (previous_set_id);
CREATE INDEX metric_results_ix2 ON metric_results (metric_id);
CREATE INDEX metric_input_facts_ix2 ON metric_input_facts (selection_fact_id);
CREATE INDEX quality_issues_ix1 ON quality_issues (report_id);
CREATE INDEX quality_issues_ix2 ON quality_issues (fact_id, report_id);
CREATE INDEX quality_issues_ix3 ON quality_issues (evidence_artifact_id);
CREATE INDEX daily_prices_ix2 ON daily_prices (artifact_id);
